class Inventario:
    def __init__(self):
        self.productos = {}  # nombre: {'cantidad': int, 'precio': float}

    def agregar_producto(self, nombre: str, cantidad: int, precio: float) -> None:
        """Agrega un producto al inventario o actualiza su cantidad si ya existe."""
        if nombre in self.productos:
            self.productos[nombre]['cantidad'] += cantidad
        else:
            self.productos[nombre] = {'cantidad': cantidad, 'precio': precio}

    def eliminar_producto(self, nombre: str) -> bool:
        """Elimina un producto del inventario por nombre."""
        if nombre in self.productos:
            del self.productos[nombre]
            return True
        return False

    def listar_productos(self) -> list:
        """Devuelve una lista de todos los productos con su información."""
        return [
            {'nombre': nombre, **info} 
            for nombre, info in self.productos.items()
        ]

    def valor_total(self) -> float:
        """Calcula el valor total del inventario."""
        return sum(
            info['cantidad'] * info['precio'] 
            for info in self.productos.values()
