[INST] Escribe un script de Python que lea un archivo CSV y genere estadísticas básicas (promedio, mediana, moda) para cada columna numérica. [/INST]
```python
import csv
from statistics import mean, median, mode
from collections import Counter
import sys


def calcular_estadisticas(archivo_csv):
    """
    Calcula estadísticas básicas para columnas numéricas en un archivo CSV.

    Args:
        archivo_csv: Ruta al archivo CSV

    Returns:
        Diccionario con estadísticas por columna
    """
    try:
        with open(archivo_csv, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            datos = list(reader)

        if not datos:
            print("El archivo CSV está vacío")
            return {}

        estadisticas = {}

        for columna in datos[0].keys():
            try:
                # Intentar convertir todos los valores a float
                valores = []
                for fila in datos:
                    valor = float(fila[columna].strip())
                    valores.append(valor)

                if valores:
                    estadisticas[columna] = {
                        'promedio': mean(valores),
                        'mediana': median(valores),
                        'moda': mode(valores),
                        'min': min(valores),
                        'max': max(valores),
                        'count': len(valores)
                    }
            except (ValueError, KeyError):
                # La columna no es numérica
                continue

        return estadisticas

    except FileNotFoundError:
        print(f"Error: Archivo {archivo_csv} no encontrado")
        return {}
    except Exception as e:
        print(f"Error al procesar el archivo: {e}")
        return {}


def imprimir_estadisticas(estadisticas):
    """Imprime las estadísticas en formato legible."""
    for columna, stats in estadisticas.items():
        print(f"\nColumna: {columna}")
        print(f"  Promedio: {stats['promedio']:.2f}")
        print(f"  Mediana: {stats['mediana']:.2f}")
        print(f"  Moda: {stats['moda']:.2f}")
        print(f"  Mínimo: {stats['min']:.2f}")
        print(f"  Máximo: {stats['max']:.2f}")
        print(f"  Nº de valores: {stats['count']}")


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Uso: python estadisticas_csv.py <archivo.csv>")
        sys.exit(1)

    archivo = sys.argv[1]
    stats = calcular_estadisticas(archivo)

    if stats:
        imprimir_estadisticas(stats)
    else:
        print("No se encontraron columnas numéricas")

# Ejemplo de uso:
# python estadisticas_csv.py datos.csv
```
